public static int[][] process(int[][] m) {
  int [][] n = {{0,0,0},{0,0,0},{0,0,0}};
  if (m.length!=3) return n;
  for (int i=0; i<3; ++i)
    if (m[i].length!=3) return n;
  for (int i=0; i<3; ++i)
    for (int j=0; j<3; ++j)
      n[i][j] = m[help1(i)][help1(j)] +
                m[help1(i)][help2(j)] +
                m[help2(i)][help1(j)] +
                m[help2(i)][help2(j)];
  return n;
}

public static int fib1(int n) {
  if (n<0) return -1;
  if (n==0) return 0;
  int n0 = 0, n1 = 1;
  while (--n > 0) {
    int temp = n1;
    n1 = n0 + n1;
    n0 = temp;
  }
  return n1;
}
public static int fib2(int n) {
  if (n<0) return -1;
  if (n==0) return 0;
  if (n==1) return 1;
  return fib2(n-1) + fib2(n-2);
}
