public static void sort(int [] a) {
  int min, minindex;
  for (int i=0; i<a.length-1; ++i) {
    min = a[i];
    minindex = i;
    for (int j=i+1; j<a.length; ++j)
      if (a[j]<a[minindex]) {
        min = a[j];
        minindex = j;
      }
    a[minindex] = a[i];
    a[i] = min;
  }
}

